for (const item of items) {
  if (item.binary && item.binary.data) {
    item.binary.data.fileName = 'audio.ogg';
    item.binary.data.fileExtension = 'ogg';
    item.binary.data.mimeType = 'audio/ogg';
  }
}
return items;

// 1. Cargar archivo
const parser = require('/home/node/virgo_files/functions/parse_special_codes.js');

// 2. Obtener datos de entrada
const item = $input.first();
const aiResponse = item.json.output || item.json.text || "";

// 3. Preparar contexto
const webhookData = $('Webhook').first().json.body.payload;
const context = { 
  phone: webhookData.from,
  executionId: $execution.id 
};

// 4. Ejecutar parser externo
const result = parser(aiResponse, context);

// ---------------------------------------------------------
// 5. PARCHES Y ETIQUETAS SECRETAS
// ---------------------------------------------------------

// Limpieza inicial de MEMORY_UPDATE
if (result.message_to_user) {
  result.message_to_user = result.message_to_user.split('MEMORY_UPDATE')[0].trim();
}

// ACTUALIZAR_NOMBRE
if (aiResponse.includes('ACTUALIZAR_NOMBRE')) {
  const match = aiResponse.match(/ACTUALIZAR_NOMBRE\s*\|\s*([^|]+)\s*\|/i);
  if (match?.[1]) {
    result.nombre_detectado = match[1].trim();
  }
}

// ACTUALIZAR_VACANTE
if (aiResponse.includes('ACTUALIZAR_VACANTE')) {
  const match = aiResponse.match(/ACTUALIZAR_VACANTE\s*\|\s*([^|]+)\s*\|/i);
  if (match?.[1]) {
    result.vacante_detectada = match[1].trim();
  }
}

// ACTUALIZAR_NAVE
if (aiResponse.includes('ACTUALIZAR_NAVE')) {
  const match = aiResponse.match(/ACTUALIZAR_NAVE\s*\|\s*([^|]+)\s*\|/i);
  if (match?.[1]) {
    result.nave_detectada = match[1].trim();
  }
}

// PRIVACIDAD_ACEPTADA
if (aiResponse.includes('PRIVACIDAD_ACEPTADA')) {
  result.acepto_privacidad = true;
}

// CITA_CANCELADA
if (aiResponse.includes('CITA_CANCELADA')) {
  result.cita_cancelada = true;
}

// CITA_CONFIRMADA
if (aiResponse.includes('CITA_CONFIRMADA')) {
  const match = aiResponse.match(/CITA_CONFIRMADA[\s:|]*(.*?)([|\n]|$)/i);
  if (match?.[1]) {
    result.fecha_entrevista_detectada = match[1].replace(/\|/g, '').trim();
  }
}

// HUMAN_ALERT
// C. Rescate de Alerta Humana ROBUSTO
if (aiResponse.includes('HUMAN_ALERT')) {
    const mensajeHumanoDefault =
        "Gracias por explicarme 😊 Voy a compartir tu caso con el equipo de reclutamiento para que puedan revisarlo y darte seguimiento por este medio.";

    let fragmento = aiResponse
        .split(/HUMAN_ALERT/i)[1]
        ?.split(/MEMORY_UPDATE/i)[0] || "";

    fragmento = fragmento.trim();

    // Quitar pipes sobrantes al inicio
    fragmento = fragmento.replace(/^\s*\|\s*/, "").trim();

    const partesRaw = fragmento.split("|").map(p => p.trim());

    // Formato correcto:
    // HUMAN_ALERT | Nombre | Resumen interno | Mensaje visible
    let nombre = "";
    let resumen = "";
    let mensajeVisible = "";

    const primerCampo = partesRaw[0] || "";

    const primerCampoPareceResumen =
        /candidato|documento|constancia|rfc|ine|cv|solicit|agend|conflict|no cuenta|no tiene/i.test(primerCampo);

    if (partesRaw.length >= 3 && !primerCampoPareceResumen) {
        nombre = partesRaw[0];
        resumen = partesRaw[1];
        mensajeVisible = partesRaw.slice(2).join(" | ").trim();
    } else if (partesRaw.length >= 2 && primerCampoPareceResumen) {
        nombre = $('ObtenerDatosCandidato').first()?.json?.nombre_chat
              || $('ObtenerDatosCandidato').first()?.json?.nombre_ine
              || $('ObtenerDatosCandidato').first()?.json?.nombre_solicitud
              || "Candidato";

        resumen = partesRaw[0];
        mensajeVisible = partesRaw.slice(1).join(" | ").trim();
    } else if (partesRaw.length >= 2) {
        nombre = partesRaw[0];
        resumen = partesRaw[1];
        mensajeVisible = mensajeHumanoDefault;
    } else {
        nombre = $('ObtenerDatosCandidato').first()?.json?.nombre_chat
              || $('ObtenerDatosCandidato').first()?.json?.nombre_ine
              || $('ObtenerDatosCandidato').first()?.json?.nombre_solicitud
              || "Candidato";

        resumen = "El candidato solicitó apoyo de reclutamiento humano.";
        mensajeVisible = mensajeHumanoDefault;
    }

    if (
        !mensajeVisible ||
        /^el candidato/i.test(mensajeVisible) ||
        /impidiendo el agendamiento/i.test(mensajeVisible) ||
        /solicitó escalamiento/i.test(mensajeVisible)
    ) {
        mensajeVisible = mensajeHumanoDefault;
    }

    result.human_alert_nombre = nombre.trim();
    result.human_alert_resumen = resumen.trim();
    result.message_to_user = mensajeVisible.trim();
}

// CV_MANUAL
if (aiResponse.includes('CV_MANUAL')) {
  const match = aiResponse.match(/CV_MANUAL[\s:|]*(\{[\s\S]*?\})/i);

  if (match?.[1]) {
    try {
      const jsonLimpio = match[1]
        .replace(/```json/gi, '')
        .replace(/```/g, '')
        .replace(/[\n\r\t]/g, ' ')
        .trim();

      const cvData = JSON.parse(jsonLimpio);

      result.experiencia_manual = cvData.experiencia;
      result.vacante_manual = cvData.vacante;
      result.datos_cv_manual = cvData;
      result.es_cv_manual = true;

      if (cvData.nombre && cvData.nombre !== "Desconocido") {
        result.nombre_detectado = cvData.nombre;
      }

    } catch (e) {
      result.datos_cv_manual = {
        error: "La IA formateó mal el JSON",
        experiencia: "Candidato llenó solicitud manual por chat."
      };
      result.es_cv_manual = true;
    }
  }
}

// RESPUESTAS_FILTRO
if (aiResponse.includes('RESPUESTAS_FILTRO')) {
  const match = aiResponse.match(
    /RESPUESTAS_FILTRO[\s:|]*([\s\S]*?)(?=\n[A-Z_]+\s*\||$)/i
  );

  if (match?.[1]) {
    result.respuestas_filtro_detectadas = match[1]
      .replace(/\|/g, '')
      .trim();
  }
}

// ENVIAR_UBICACION
if (aiResponse.includes('ENVIAR_UBICACION')) {
  result.enviar_ubicacion = true;
}

// ---------------------------------------------------------
// 6. LIMPIEZA VISUAL PROFUNDA
// ---------------------------------------------------------

if (result.message_to_user) {
  result.message_to_user = result.message_to_user
    .replace(/ACTUALIZAR_NOMBRE\s*\|\s*[^|]+\s*\|/gi, '')
    .replace(/ACTUALIZAR_VACANTE\s*\|\s*[^|]+\s*\|/gi, '')
    .replace(/ACTUALIZAR_NAVE\s*\|\s*[^|]+\s*\|/gi, '')
    // Limpieza de etiquetas internas de vacantes (no deben llegar al candidato)
    .replace(/^\s*\[REQUISITO EXCLUSIVO:\s*[^\]]+\]\s*$/gim, '')
    .replace(/\s*\[REQUISITO EXCLUSIVO:\s*[^\]]+\]\s*/gi, '')
    .replace(/^\s*\[(CONTROL_INTERNO|PERFIL|CONDICIONES_OPERATIVAS|REQUISITO_FISICO):[^\]]+\]\s*$/gim, '')
    .replace(/\s*\[(CONTROL_INTERNO|PERFIL|CONDICIONES_OPERATIVAS|REQUISITO_FISICO):[^\]]+\]\s*/gi, '')
    .replace(/PRIVACIDAD_ACEPTADA\s*\|?/gi, '')
    .replace(/CITA_CONFIRMADA[\s:|]*(.*?)([|\n]|$)/gi, '')
    .replace(/CITA_CANCELADA[\s:|]*(.*?)([|\n]|$)/gi, '')
    .replace(/ENVIAR_UBICACION[\s:|]*(.*?)([|\n]|$)/gi, '')
    .replace(/RESPUESTAS_FILTRO[\s:|]*([\s\S]*?)(?=\n[A-Z_]+\s*\||$)/gi, '')
    .replace(/CV_MANUAL[\s:|]*\{[\s\S]*?\}/gi, '')
    .replace(/```json/gi, '')
    .replace(/```/g, '')
    .replace(/[ \t]+\n/g, '\n')
    .replace(/\n{3,}/g, '\n\n')
    result.message_to_user = result.message_to_user.replace(/^\s*\[REQUISITO EXCLUSIVO:\s*[^\]]+\]\s*$/gim, '').trim();
    result.message_to_user = result.message_to_user.replace(/\s*\[REQUISITO EXCLUSIVO:\s*[^\]]+\]\s*/gi, '').trim();
    result.message_to_user = result.message_to_user.replace(/^\s*\[(CONTROL_INTERNO|PERFIL|CONDICIONES_OPERATIVAS|REQUISITO_FISICO):[^\]]+\]\s*$/gim, '')
    result.message_to_user = result.message_to_user.replace(/\s*\[(CONTROL_INTERNO|PERFIL|CONDICIONES_OPERATIVAS|REQUISITO_FISICO):[^\]]+\]\s*/gi, '')
    .trim();

  if (result.fecha_entrevista_detectada) {
    result.message_to_user = result.message_to_user
      .replace(result.fecha_entrevista_detectada, '')
      .replace(/\|/g, '')
      .trim();
  }

  // Protección final contra filtrado de HUMAN_ALERT
  if (
      /^el candidato/i.test(result.message_to_user) ||
      result.message_to_user.includes("impidiendo el agendamiento") ||
      result.message_to_user.includes("Solicitó escalamiento") ||
      result.message_to_user.includes("solicitó escalamiento")
  ) {
      result.message_to_user =
          "Gracias por explicarme 😊 Voy a compartir tu caso con el equipo de reclutamiento para que puedan revisarlo y darte seguimiento por este medio.";
  }

  if (
      result.message_to_user.includes("|") &&
      /^el candidato/i.test(result.message_to_user)
  ) {
      const partes = result.message_to_user.split("|").map(p => p.trim()).filter(Boolean);
      result.message_to_user = partes[partes.length - 1] ||
          "Gracias por explicarme 😊 Voy a compartir tu caso con el equipo de reclutamiento para que puedan revisarlo y darte seguimiento por este medio.";
  }

  result.message_to_user = result.message_to_user
    .replace(/^[|\s]+/, '')
    .trim();
}

// Protección final si quedó vacío
if (!result.message_to_user || result.message_to_user.trim() === "") {
  result.message_to_user =
    "Gracias por tu mensaje 😊 Permíteme revisar la información para poder ayudarte mejor.";
}

// ---------------------------------------------------------
// 7. SPLIT DE MENSAJES
// ---------------------------------------------------------

let mensajes = [result.message_to_user];

if (result.message_to_user.includes('[SPLIT]')) {
  mensajes = result.message_to_user
    .split(/\[SPLIT\]/i)
    .map(m => m.trim())
    .filter(m => m !== "");
}

let output = [];

for (let msg of mensajes) {
  let itemCopia = JSON.parse(JSON.stringify(result));

  itemCopia.message_to_user = msg;

  if (result.nombre_detectado) itemCopia.nombre_detectado = result.nombre_detectado;
  if (result.acepto_privacidad) itemCopia.acepto_privacidad = true;
  if (result.experiencia_manual) itemCopia.experiencia_manual = result.experiencia_manual;
  if (result.vacante_manual) itemCopia.vacante_manual = result.vacante_manual;
  if (result.respuestas_filtro_detectadas) itemCopia.respuestas_filtro_detectadas = result.respuestas_filtro_detectadas;
  if (result.vacante_detectada) itemCopia.vacante_detectada = result.vacante_detectada;
  if (result.datos_cv_manual) itemCopia.datos_cv_manual = result.datos_cv_manual;
  if (result.es_cv_manual) itemCopia.es_cv_manual = result.es_cv_manual;
  if (result.fecha_entrevista_detectada) itemCopia.fecha_entrevista_detectada = result.fecha_entrevista_detectada;
  if (result.nave_detectada) itemCopia.nave_detectada = result.nave_detectada;

  if (result.human_alert_nombre) itemCopia.human_alert_nombre = result.human_alert_nombre;
  if (result.human_alert_resumen) itemCopia.human_alert_resumen = result.human_alert_resumen;
  if(result.human_alert_nombre) itemCopia.human_alert_nombre = result.human_alert_nombre;
  if(result.human_alert_resumen) itemCopia.human_alert_resumen = result.human_alert_resumen;
  if(result.nave_detectada) itemCopia.nave_detectada = result.nave_detectada;

  output.push({ json: itemCopia });
}

return output;

