// a texto legible para el reclutador humano. Si el resumen no viene en ese formato
// (ej. quedó en el formato largo anterior), se regresa tal cual sin modificar.
function expandirResumenComprimido(texto) {
    if (!texto) return "Sin resumen previo disponible.";

    const esFormatoComprimido = /\bN:|V:|E:|Priv:|CV:|INE:|RFC:|Cita:/.test(texto);
    if (!esFormatoComprimido) return texto;

    const get = (regex) => {
        const m = texto.match(regex);
        return m ? m[1].trim() : null;
    };

    const nombre = get(/N:([^V]*?)(?=\s+V:|$)/);
    const vacante = get(/V:([^E]*?)(?=\s+E:|$)/);
    const etapa = get(/E:([^P]*?)(?=\s+Priv:|$)/);
    const privacidad = get(/Priv:([^\s]*)/);
    const cv = get(/CV:([^\s]*)/);
    const ine = get(/INE:([^\s]*)/);
    const rfc = get(/RFC:([^\s]*)/);
    const cita = get(/Cita:([^N]*?)(?=\s+Notas:|$)/);
    const notas = get(/Notas:(.*)$/);

    const siNo = (v) => v === 'S' ? 'Sí' : v === 'N' ? 'No' : (v || 'N/D');

    let partes = [];
    if (nombre) partes.push(`Nombre: ${nombre}`);
    if (vacante) partes.push(`Vacante: ${vacante}`);
    if (etapa) partes.push(`Etapa: ${etapa}`);
    if (privacidad) partes.push(`Privacidad aceptada: ${siNo(privacidad)}`);
    if (cv) partes.push(`CV recibido: ${siNo(cv)}`);
    if (ine) partes.push(`INE recibido: ${siNo(ine)}`);
    if (rfc) partes.push(`RFC recibido: ${siNo(rfc)}`);
    if (cita) partes.push(`Cita: ${cita.trim() === 'N' ? 'pendiente' : cita.trim()}`);
    if (notas) partes.push(`Notas: ${notas.trim()}`);

