return { json: { latitud: lat, longitud: lon, titulo: titulo } };

// Este nodo corre DESPUÉS de TurnoReclutador (Postgres)
// Si solo había 1 candidato, DefinirAgenda ya lo resolvió y grupo_turno = null
// Si había varios, TurnoReclutador devuelve el index que toca ahora

const agenda = $('DefinirAgenda').first().json;

// Caso 1: sin turno (1 solo reclutador o gerente fallback)
if (!agenda.grupo_turno) {
    return { json: agenda };
}

// Caso 2: turno activo → usar el index devuelto por Postgres
const turnoIndex = $input.first().json.ultimo_index ?? 0;
const candidatos = JSON.parse(agenda.candidatos_turno);
const asignado = candidatos[turnoIndex];

return {
    json: {
        nombre_reclutador: asignado.nombre,
        telefono_reclutador: asignado.telefono,
        calendar_id: asignado.calendar_id,
        vacante_detectada: agenda.vacante_detectada,
        nave_candidato: agenda.nave_candidato,
        grupo_turno: agenda.grupo_turno,
        turno_index: turnoIndex
    }
};

